dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": [
        {
          "label": "POAG",
          "value": "VG_POAG"
        },
        {
          "label": "Intraocular Pressure",
          "value": "VG_intraocular_pressure"
        }
      ]
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "Cross-ancestry",
          "value": "Mixed"
        },
        {
          "label": "European",
          "value": "eu"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Set region (chr:start-end)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000,
      "search point": "https://vision.hugeampkpnbi.org"
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://bioindex-dev.hugeamp.org/api/bio/keys/gene-links/2?columns=tissue",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "gene",
      "label": "gene",
      "type": "input",
      "display": "false"
    }
  ],
  "tab groups": [
    {
      "label": "Summary",
      "type": "fixed bottom",
      "sections": [
        {
          "section": "page_summary",
          "label": "Page Summary"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "variant_links_gene_sqtl",
      "header": "sQTLs: by Region",
      "data point": {
        "type": "bioindex",
        "url": "https://vision.hugeampkpnbi.org/api/bio/",
        "index": "variant-links",
        "parameters": [
          "region"
        ],
        "region": "region",
        "parameters type": "array",
        "data type": "bioindex"
      },
      "pre filters": [
        {
          "field": "Method",
          "value": "sQTLs",
          "type": "search"
        }
      ],
      "table format": {
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "star column": "Variant ID",
        "data convert": [
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "start"
          },
          {
            "type": "raw",
            "field name": "variant_links Position",
            "raw field": "start"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "QTL_beta"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "QTL_p"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-value)",
            "raw field": "QTL_p",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Start",
            "raw field": "start"
          },
          {
            "type": "calculate",
            "field name": "End",
            "expression": [
              "end",
              "+",
              2
            ],
            "calculation type": "math"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "Start",
              "Start"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "Linked Genes",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Target Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "State",
            "raw field": "state"
          },
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "variant"
          },
          {
            "type": "join multi",
            "field name": "Variant_tissue",
            "fields to join": [
              "Variant ID",
              "Tissue"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Splice ID",
            "raw field": "splice_id"
          },
          {
            "type": "raw",
            "field name": "Cluster ID",
            "raw field": "cluster_id"
          },
          {
            "type": "join multi",
            "field name": "Splice event",
            "fields to join": [
              "splice_start",
              "splice_end"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Splice ID_Linked gene",
            "fields to join": [
              "Splice ID",
              "Linked Genes"
            ],
            "join by": [
              "_"
            ]
          }
        ],
        "top rows": [
          "Variant ID",
          "Linked Genes",
          "Tissue",
          "Biosample",
          "P-value",
          "Beta",
          "Cluster ID",
          "Splice ID",
          "Splice event",
          "Dataset",
          "Source",
          "State"
        ],
        "column formatting": {
          "Tissue": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Set Tissue",
                "parameter": [
                  "tissue"
                ]
              }
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Linked Genes",
          "label": "Linked Genes",
          "type": "checkbox"
        }
      ],
      "visualizers": {
        "wrapper type": "divs",
        "visualizers": [
          {
            "label": "Gene by splicing event (start:end) per track, colorcoding by tissue",
            "type": "region track",
            "zoom": "true",
            "render by": "Region",
            "x axis field": "Position",
            "y axis field": "Splice ID",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Splice ID",
              "Method",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Tissue",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            },
            "genome reference": "GRCh38"
          }
        ],
        "unused": [
          {
            "label": "Annotated regions (grouped by Splice ID_Linked gene, colored by Cluster ID)",
            "type": "region track",
            "zoom": "true",
            "render by": "Region",
            "x axis field": "Position",
            "y axis field": "Splice ID_Linked gene",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Splice ID",
              "Method",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Cluster ID",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            },
            "genome reference": "GRCh38"
          },
          {
            "label": "Annotated regions (grouped by tissues, colored by linked genes)",
            "type": "region track",
            "zoom": "true",
            "render by": "Region",
            "x axis field": "Position",
            "y axis field": "Tissue",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Splice ID",
              "Method",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Linked Genes",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            },
            "genome reference": "GRCh38"
          },
          {
            "label": "Annotated regions (grouped by tissues, colored by Splice ID)",
            "type": "region track",
            "zoom": "true",
            "render by": "Region",
            "x axis field": "Position",
            "y axis field": "Tissue",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Method",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Splice ID",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            },
            "genome reference": "GRCh38"
          },
          {
            "label": "Annotated regions (grouped by linked genes, colored by tissues)",
            "type": "region track",
            "zoom": "true",
            "render by": "Region",
            "x axis field": "Position",
            "y axis field": "Linked Genes",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Method",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Tissue",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            }
          },
          {
            "label": "Annotated regions (grouped by linked genes, colored by Splice ID)",
            "type": "region track",
            "zoom": "true",
            "render by": "Region",
            "x axis field": "Position",
            "y axis field": "Linked Genes",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Splice ID",
              "Method",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Splice ID",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            }
          },
          {
            "label": "Splicing region (grouped by linked genes, colored by tissues)",
            "type": "region track",
            "zoom": "true",
            "render by": "Splice event",
            "x axis field": "Position",
            "y axis field": "Linked Genes",
            "hover content": [
              "Variant ID",
              "Biosample",
              "Splice event",
              "P-value",
              "Beta",
              "Dataset",
              "Source",
              "State"
            ],
            "color by": "Tissue",
            "track height": 12,
            "plot margin": {
              "left": 200,
              "right": 200,
              "top": 30,
              "bottom": 100,
              "bump": 10
            }
          },
          {
            "label": "Rendered by variants",
            "star key": "Variant ID",
            "zoom": "true",
            "type": "region plot",
            "genome reference": "GRCh38",
            "x axis field": "Position",
            "y axis field": "-log10(P-value)",
            "render by": "Variant_tissue",
            "y axis label": "-Log10(p-value)",
            "x axis label": "Chromosome",
            "hover content": [
              "P-value",
              "Beta"
            ],
            "height": 120,
            "plot margin": {
              "left": 200,
              "right": 100,
              "top": 30,
              "bottom": 100,
              "bump": 10
            },
            "ld server": {
              "pos": "Position",
              "ref": "ref",
              "alt": "alt",
              "ref variant field": "Variant ID",
              "populations field": "P-value",
              "populations type": "fixed",
              "fixed population": "ALL",
              "populations": {
                "ALL": "ALL"
              }
            },
            "genes track": {
              "input type": "dynamic",
              "dynamic parameter": "region",
              "search point": "https://vision.hugeampkpnbi.org"
            },
            "input type": "dynamic",
            "dynamic parameter": "region",
            "if combine y axis field": {
              "type": "average",
              "field": "-log10(P-value)"
            }
          }
        ]
      }
    },
    {
      "section id": "page_summary",
      "header": "Summary",
      "is summary section": "true",
      "sections": {
        "primary section": "associations",
        "sub sections": [
          {
            "section": "variant_links_gene_eqtl",
            "label": "eQTL by Region",
            "actions": [
              {
                "action": "filter",
                "filter field": "variant_links Position",
                "target field": "Position",
                "type": "search"
              },
              {
                "action": "add top columns",
                "columns": [
                  {
                    "column": "Linked Genes",
                    "key field": "variant_links Position",
                    "if multiple values": "replace"
                  }
                ]
              },
              {
                "action": "add features",
                "feature": "Variant2Gene",
                "key field": "variant_links Position",
                "columns": [
                  "Variant ID",
                  "Linked Genes",
                  "Biosample",
                  "Method",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "if multiple values": "add"
              }
            ]
          },
          {
            "section": "variant_links_gene_sqtl",
            "label": "sQTL by Region",
            "actions": [
              {
                "action": "filter",
                "filter field": "variant_links Position",
                "target field": "Position",
                "type": "search"
              },
              {
                "action": "add top columns",
                "columns": [
                  {
                    "column": "Linked Genes",
                    "key field": "variant_links Position",
                    "if multiple values": "replace"
                  }
                ]
              },
              {
                "action": "add features",
                "feature": "Variant2Gene",
                "key field": "variant_links Position",
                "columns": [
                  "Variant ID",
                  "Linked Genes",
                  "Biosample",
                  "Method",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "if multiple values": "add"
              }
            ]
          },
          {
            "section": "gene_links",
            "label": "Gene Links in Enriched Biosamples",
            "actions": [
              {
                "action": "filter",
                "filter field": "gene_links Filter Region",
                "target field": "Position",
                "type": "search and"
              },
              {
                "action": "add top columns",
                "columns": [
                  {
                    "column": "Target Gene",
                    "key field": "gene_links Filter Region",
                    "if multiple values": "add"
                  }
                ]
              },
              {
                "action": "add features",
                "feature": "gene_links",
                "key field": "gene_links Filter Region",
                "columns": [
                  "Region",
                  "Target Gene",
                  "Target Region in Gene",
                  "Method",
                  "Source",
                  "Dataset",
                  "Assay",
                  "Tissue",
                  "Biosample"
                ],
                "if multiple values": "add"
              }
            ]
          }
        ]
      }
    }
  ],
  "unused sections": [
    {
      "section id": "associations",
      "header": "Associated Variants in Region",
      "data point": {
        "type": "bioindex",
        "url": "https://vision.hugeampkpnbi.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region",
        "cumulate data": "true"
      },
      "table format": {
        "initial sort by": {
          "field": "P-value",
          "type": "number",
          "direction": "desc"
        },
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "group by": [
          "PhenotypeAncestry"
        ],
        "compare data": {
          "key field": "Variant ID",
          "fields to compare": [
            "PhenotypeAncestry",
            "phenotype_ancestry",
            "-log10(P-Value)",
            "P-Value",
            "Beta",
            "MAF",
            "Standard Error",
            "Z Score"
          ]
        },
        "data convert": [
          {
            "type": "replace characters",
            "field name": "Phenotype",
            "raw field": "phenotype",
            "replace": [
              {
                "from": "VG_",
                "to": ""
              },
              {
                "from": "Mixed",
                "to": "CrossAnc"
              },
              {
                "from": "EU",
                "to": "EUR"
              },
              {
                "from": "Intraocular_pressure",
                "to": "IOP"
              }
            ]
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "PhenotypeAncestry",
            "fields to join": [
              "Phenotype",
              "Ancestry"
            ],
            "join by": "_"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "calculate",
            "field name": "-log10(P-value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "PhenotypeAncestry",
          "phenotype_ancestry",
          "Ref/Alt",
          "P-value",
          "Beta",
          "Standard Error",
          "Z Score"
        ],
        "tool tips": {
          "Variant ID": "chromosome:position (hg19)_ref/alt",
          "rsID": "Variant ID from dbGaP",
          "Ref/Alt": "Reference allele/alternate allele",
          "P-value": "Significance of association with the selected phenotype(s)",
          "Beta": "Effect size",
          "MAF": "Minor allele frequency",
          "Z Score": "Beta / Standard error",
          "Consequence": "Impact of the variant for overlapping genes or transcripts, as predicted by the Ensembl Variant Effect Predictor (VEP)",
          "Credible Set": "Posterior Probability of Association for the variant in the selected credible set(s)"
        },
        "star column": "Variant ID",
        "locus field": "Locus",
        "column formatting": {
          "P-value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-value",
          "label": "P-value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Phenotype",
          "label": "Phenotype",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Ancestry",
          "label": "Ancestry",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "star key": "Variant ID",
        "zoom": "true",
        "type": "region plot",
        "genome reference": "GRCh38",
        "x axis field": "Position",
        "y axis field": "-log10(P-value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-value",
          "Beta"
        ],
        "height": 120,
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region",
          "search point": "https://vision.hugeampkpnbi.org"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-value)"
        },
        "plot margin": {
          "left": 200,
          "right": 100,
          "top": 30,
          "bottom": 100,
          "bump": 10
        }
      }
    }
  ]
}
